package dev.sense.lockscreen;

import android.app.*;
import android.content.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.util.function.BooleanSupplier;

/** Emulator only. Uses power/keyguard commands, never sets, reads or changes a credential. */
final class AfterUnlockInstrumentation {
    private final android.app.Instrumentation test;private final Context context;private Activity settings,screen;
    AfterUnlockInstrumentation(android.app.Instrumentation test){this.test=test;context=test.getTargetContext();}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void await(BooleanSupplier condition,String message)throws Exception{long end=SystemClock.uptimeMillis()+6000;while(SystemClock.uptimeMillis()<end){if(condition.getAsBoolean())return;SystemClock.sleep(60);}throw new AssertionError(message);}
    private void shell(String command)throws Exception{try(var input=new android.os.ParcelFileDescriptor.AutoCloseInputStream(test.getUiAutomation().executeShellCommand(command))){input.readAllBytes();}}
    private View find(View v,String text){if(v instanceof TextView label&&text.contentEquals(label.getText()))return v;if(v instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){View found=find(group.getChildAt(i),text);if(found!=null)return found;}return null;}
    private boolean notification(){for(var notification:context.getSystemService(NotificationManager.class).getActiveNotifications())if(notification.getId()==21)return true;return false;}
    void run(){Bundle report=new Bundle();var prefs=context.getSharedPreferences("lockscreen",0);boolean had=prefs.contains(AfterUnlockService.ENABLED),before=AfterUnlockService.enabled(context);android.app.Instrumentation.ActivityMonitor monitor=null;int result=Activity.RESULT_CANCELED;
        try{
            check(android.os.Build.PRODUCT.contains("sdk"),"Interactive suite is emulator-only");check(!context.getSystemService(KeyguardManager.class).isDeviceSecure(),"Interactive test requires an emulator without an existing secure credential");check(Settings.canDrawOverlays(context),"Test host must temporarily grant overlay access");
            AfterUnlockPolicy policy=new AfterUnlockPolicy(false);check(!policy.userPresent(true,true,true,false,false),"Enabling alone displayed a screen");policy.screenOff();check(!policy.userPresent(true,true,true,true,false),"HTC appeared before system unlock");check(policy.userPresent(true,true,true,false,false),"Unlocked cycle was not presented");check(!policy.userPresent(true,true,true,false,false),"Cycle presented twice");policy.screenOff();policy.suppress();check(!policy.userPresent(true,true,true,false,false),"Manual authentication reopened HTC");policy.screenOff();check(!policy.userPresent(false,true,true,false,false),"Disabled toggle displayed HTC");policy.screenOff();check(!policy.userPresent(true,false,true,false,false),"Missing permission displayed HTC");policy.screenOff();check(!policy.userPresent(true,true,true,false,true),"Already visible screen was relaunched");
            prefs.edit().putBoolean(AfterUnlockService.ENABLED,false).commit();context.stopService(new Intent(context,AfterUnlockService.class));
            settings=test.startActivitySync(new Intent(context,LockScreenSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));test.waitForIdleSync();test.runOnMainSync(()->{View toggle=find(settings.getWindow().getDecorView(),"Show after system unlock");check(toggle instanceof Switch,"After-unlock toggle missing");toggle.performClick();});check(AfterUnlockService.enabled(context),"Toggle did not persist");await(this::notification,"Foreground notification missing");await(AfterUnlockService::listening,"Unlock listener not registered");
            shell("input keyevent 3");shell("input keyevent 223");await(()->!context.getSystemService(PowerManager.class).isInteractive(),"Emulator did not sleep");await(AfterUnlockService::armed,"Screen-off event was not delivered");monitor=test.addMonitor(LockScreenActivity.class.getName(),null,false);shell("input keyevent 224");shell("wm dismiss-keyguard");screen=test.waitForMonitorWithTimeout(monitor,6000);check(screen instanceof LockScreenActivity,"HTC activity did not appear after system unlock");test.removeMonitor(monitor);monitor=null;test.waitForIdleSync();check(screen.getIntent().getBooleanExtra("afterSystemUnlock",false),"Screen was not launched by after-unlock mode");check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"System keyguard is still locked");Activity active=screen;test.runOnMainSync(active::finishAndRemoveTask);screen=null;
            settings=test.startActivitySync(new Intent(context,LockScreenSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));test.runOnMainSync(()->find(settings.getWindow().getDecorView(),"Show after system unlock").performClick());check(!AfterUnlockService.enabled(context),"Toggle did not disable");await(()->!notification(),"Foreground service did not stop");shell("input keyevent 3");monitor=test.addMonitor(LockScreenActivity.class.getName(),null,false);shell("input keyevent 223");await(()->!context.getSystemService(PowerManager.class).isInteractive(),"Emulator did not sleep for disabled check");shell("input keyevent 224");shell("wm dismiss-keyguard");check(test.waitForMonitorWithTimeout(monitor,1500)==null,"Disabled feature still opened HTC");
            report.putString("result","PASS: opt-in toggle, notification, real system unlock launch, disabled cycle, duplicate/suppressed/locked/permission guards; no credentials changed");result=Activity.RESULT_OK;
        }catch(Throwable error){report.putString("error",android.util.Log.getStackTraceString(error));}finally{if(monitor!=null)test.removeMonitor(monitor);if(screen!=null){Activity active=screen;test.runOnMainSync(active::finishAndRemoveTask);}if(settings!=null){Activity active=settings;test.runOnMainSync(active::finish);}var restore=prefs.edit();if(had)restore.putBoolean(AfterUnlockService.ENABLED,before);else restore.remove(AfterUnlockService.ENABLED);restore.commit();try{AfterUnlockService.reconcile(context);}catch(RuntimeException ignored){}}test.finish(result,report);
    }
}
